@extends('layouts.app') @section('content')<h1>{{ $invoice ? 'Edit' : 'New' }} {{ $type }} invoice</h1><form method="post" action="{{ $invoice ? route('invoices.update',[$type,$invoice]) : route('invoices.store',$type) }}">@csrf @if($invoice) @method('PUT') @endif<div class="row"><div class="col-md-6 mb-3"><label>{{ $type==='purchase'?'Supplier':'Customer' }}</label><select name="party_id" class="form-select" required>@foreach($parties as $party)<option value="{{ $party->id }}" @selected($invoice && $invoice->{$type==='purchase'?'supplier_id':'customer_id'}==$party->id)>{{ $party->name }}</option>@endforeach</select></div><div class="col-md-3 mb-3"><label>Issue date</label><input type="date" name="issue_date" class="form-control" value="{{ old('issue_date',$invoice?->issue_date?->toDateString() ?? now()->toDateString()) }}" required></div><div class="col-md-3 mb-3"><label>Due date</label><input type="date" name="due_date" class="form-control" value="{{ old('due_date',$invoice?->due_date?->toDateString() ?? now()->addDays(30)->toDateString()) }}" required></div></div><div id="items">@foreach(old('items',$invoice?->items?->toArray() ?? [['description'=>'','quantity'=>'','unit_price'=>'','tax_rate'=>0]]) as $i=>$item)<div class="row mb-2"><div class="col"><input name="items[{{$i}}][description]" class="form-control" value="{{ $item['description']??'' }}" required></div><div class="col"><input name="items[{{$i}}][quantity]" type="number" step=".01" class="form-control" value="{{ $item['quantity']??'' }}" required></div><div class="col"><input name="items[{{$i}}][unit_price]" type="number" step=".01" class="form-control" value="{{ $item['unit_price']??'' }}" required></div><div class="col"><input name="items[{{$i}}][tax_rate]" type="number" step=".01" class="form-control" value="{{ $item['tax_rate']??0 }}"></div></div>@endforeach</div><button type="button" class="btn btn-sm btn-outline-secondary" onclick="addItem()">Add line</button><div class="row mt-3"><div class="col"><input name="discount_value" class="form-control" value="{{ old('discount_value',$invoice?->discount_value ?? 0) }}" placeholder="Discount"></div><div class="col"><select name="discount_type" class="form-select"><option value="flat">Flat</option><option value="percent">Percent</option></select></div><div class="col"><input name="tax_rate" class="form-control" value="{{ old('tax_rate',$invoice?->tax_rate ?? 0) }}" placeholder="Invoice tax %"></div></div><button class="btn btn-primary mt-3">Save invoice</button></form><script>let i={{ count(old('items',$invoice?->items?->toArray() ?? [[]])) }};function addItem(){items.insertAdjacentHTML('beforeend',`<div class="row mb-2"><div class="col"><input name="items[${i}][description]" class="form-control" required></div><div class="col"><input name="items[${i}][quantity]" type="number" step=".01" class="form-control" required></div><div class="col"><input name="items[${i}][unit_price]" type="number" step=".01" class="form-control" required></div><div class="col"><input name="items[${i}][tax_rate]" type="number" step=".01" class="form-control" value="0"></div></div>`);i++}</script>@endsection
